/** Closest physical copy of an original snap point, including on later turns. */
export function nearestSnap(target: any, times: any, count: any, speed: any, cycleWidth: any, maxScroll: any, loop: any): {
    index: number;
    position: any;
};
export function stretch(raw: any, max: any, width: any, elasticity: any): number;
export function unstretch(shown: any, max: any, width: any, elasticity: any): any;
export function stretchRate(shown: any, max: any, width: any, elasticity: any): number;
